"""Apply reviewed AgentID edits to the pinned source, then remove in the check job.

The compressed JSON contains only [path, old text, new text, count] records.
It is data, never executable code. No application credential is included.
"""
import base64
import hashlib
import json
import subprocess
import zlib
from pathlib import Path

BASE = '2d89b3313bd3324e6eefcb87a4d3747753bed73f'
SHA256 = 'b576b6c8e6d15b5bbc3299a496405dfe2a3eae8e58924caccc0c672e29da6c27'
PATCH = ''''''

raw = zlib.decompress(base64.b64decode(PATCH))
if hashlib.sha256(raw).hexdigest() != SHA256:
    raise SystemExit('Reviewed edit data checksum mismatch')
edits = json.loads(raw)
paths = sorted({entry[0] for entry in edits})
subprocess.run(['git', 'diff', '--exit-code', BASE, '--', *paths], check=True)
updates = {path: Path(path).read_text() for path in paths}
for path, old, new, expected in edits:
    if updates[path].count(old) != expected:
        raise SystemExit('Source precondition mismatch: ' + path)
    updates[path] = updates[path].replace(old, new)
for path, text in updates.items():
    Path(path).write_text(text)
print('Applied guarded AgentID changes to', len(paths), 'files')
